function toast(msg, undo) {
  const sb = $("#snackbar");
  $("#snackText").textContent = msg;
  $("#snackUndo").style.display = undo ? "" : "none";
  $("#snackUndo").onclick = () => { sb.hidden = true; if (undo) undo(); };
  sb.hidden = false;
  clearTimeout(undoTimer);
  undoTimer = setTimeout(() => (sb.hidden = true), 6000);
}

// ---------- Load ----------
// Fresh load: fetch the first page (PAGE items) and REPLACE the current view.
async function load() {
  $("#loading").hidden = false;
  $("#loading").textContent = "Loading…";
  const v = STATE.view;
  const lim = "limit=" + PAGE;
  let d;
  if (v === "inbox") {
    d = await api("/api/inbox?" + lim);
    STATE.inboxCache = d;
    STATE.token = d.nextPageToken || null;
  } else if (v === "pinned") {
    const i = await api("/api/inbox?" + lim);
    STATE.inboxCache = i;
    STATE.token = i.nextPageToken || null;
    d = { items: i.pinned || [], email: i.email };
  } else if (v === "snoozed") {
    d = await api("/api/snoozed?" + lim);
    STATE.token = d.nextPageToken || null;

@app.route("/api/to_things", methods=["POST"])
def api_to_things():
    d = request.json
    tid = d["threadId"]
    title = d.get("title", "(email)")
    sender = d.get("sender", "")
    snippet = d.get("snippet", "")
    permalink = gmail_permalink(tid)
    backlink = f"inboxclone://thread/{tid}?gmail={quote(permalink, safe='')}"
    notes = f"{backlink}\n\nGmail (fallback): {permalink}\n\nFrom: {sender}\n{snippet}"
    things = f"things:///add?title={quote(title)}&notes={quote(notes)}"
    try:
        subprocess.run(["open", things], check=True)
        return jsonify({"ok": True})
    except Exception as e:
        return jsonify({"error": str(e), "url": things}), 500


def start_background():
    """Migrate the DB, start the Deferred Action Engine, trigger auth, poll history."""
    migrate_db()
    threading.Thread(target=_scheduler_loop, daemon=True).start()
    # Trigger auth before serving so the consent flow opens cleanly on first run
    try:
        get_service()
    except Exception as e:
        print(f"[auth] deferred: {e}")
    threading.Thread(target=_history_loop, daemon=True).start()


def run_server():
    start_background()
    # threaded=True is required: SSE connections are long-lived and must not block other requests
    app.run(host="127.0.0.1", port=PORT, debug=False, threaded=True, use_reloader=False)


if __name__ == "__main__":
    run_server()

