function clearCompose() { $("#cTo").value = $("#cSubject").value = $("#cCc").value = $("#cBcc").value = ""; $("#cBody").innerHTML = ""; STATE.attachments = []; STATE.fwdAttachments = []; renderAttachChips(); renderFwdChips(); }
