  if (STATE.view === "inbox") {
    if ($("#pinnedOnly").checked) return d.pinned?.length || 0;
    return (d.pinned?.length || 0) + (d.primary?.length || 0) + (d.bundles || []).reduce((s, b) => s + (b.count || 0), 0);
